from pathlib import Path
import itertools

def transform(grid):
    cells={(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==8}
    n,m=len(grid),len(grid[0])
    options=[]
    for r in range(n-1):
        for c in range(m-1):
            block={(r+i,c+j) for i in range(2) for j in range(2)}
            if block<=cells: options.append((1,block))
            for miss in block:
                piece=block-{miss}
                if piece<=cells:
                    # color by missing corner: TL=2, BL=3, TR=4, BR=? only observed types
                    color={(r,c):2,(r+1,c):3,(r,c+1):4,(r+1,c+1):5}[miss]
                    options.append((color,piece))
    # Exact cover; find cover with fewest options; deterministic
    sols=[]
    def rec(rem, chosen):
        if not rem:
            sols.append(chosen); return
        x=min(rem)
        for color,piece in options:
            if x in piece and piece<=rem:
                rec(rem-piece,chosen+[(color,piece)])
                if len(sols)>1: return
    rec(cells,[])
    if not sols: raise ValueError('no tiling')
    out=[[0]*m for _ in range(n)]
    for color,piece in sols[0]:
        for r,c in piece: out[r][c]=color
    return out

