    height, width = len(grid), len(grid[0])
    options = []
    for r in range(height - 1):
        for c in range(width - 1):
            block = {(r + dr, c + dc) for dr in range(2) for dc in range(2)}
            if block <= cells:
                options.append((1, block))
            colors = {(r, c): 2, (r + 1, c): 3, (r, c + 1): 4, (r + 1, c + 1): 5}
            for missing, color in colors.items():
                piece = block - {missing}
                if piece <= cells:
                    options.append((color, piece))
    solutions = []
    def cover(remaining, chosen):
        if not remaining:
            solutions.append(chosen)
            return
        cell = min(remaining)
        for color, piece in options:
            if cell in piece and piece <= remaining:
                cover(remaining - piece, chosen + [(color, piece)])
                if solutions:
                    return
    cover(cells, [])
    if not solutions:
        raise ValueError("No exact tiling found")
    output = [[0] * width for _ in range(height)]
    for color, piece in solutions[0]:
        for r, c in piece:
            output[r][c] = color
    return output
